// Business Analyst Chat Handler - Pipeline Specific
const input = $input.all()[0].json;
const intent = input.intent || 'help';
const projectSlug = input.projectSlug || null;
const query = input.query || input.rawInput || '';

const STAGE = 'business-analysis';
const ARTIFACT_TYPE = 'brd';

let response = {
  agent: 'Business Analyst',
  stage: STAGE,
  intent: intent,
  success: true
};

switch (intent) {
  case 'help':
    response.content = `# Business Analyst Pipeline\n\n## Available Commands\n\n| Command | Description |\n|---------|-------------|\n| help | Show this help message |\n| status [project] | Check job status for a project |\n| artifacts [project] | List BRD artifacts for a project |\n| jobs | List recent jobs for this pipeline |\n| list | List all projects |\n\n## Execute Mode\n\nTo generate a BRD, send a request like:\n\`\`\`\nBuild me a task management API with CRUD operations\n\`\`\`\n\nOr with explicit parameters:\n\`\`\`json\n{\n  "requirements": "Your requirements...",\n  "projectSlug": "my-project",\n  "projectName": "My Project"\n}\n\`\`\``;
    response.message = 'Business Analyst Help';
    break;

  case 'status':
    response.action = 'query_db';
    response.queryType = 'status';
    response.sql = projectSlug 
      ? `SELECT j.id, j.stage, j.status, j.created_at, j.completed_at, p.slug, p.name FROM architecture.jobs j JOIN architecture.projects p ON j.project_id = p.id WHERE j.stage = '${STAGE}' AND p.slug = '${projectSlug}' ORDER BY j.created_at DESC LIMIT 5`
      : `SELECT j.id, j.stage, j.status, j.created_at, j.completed_at, p.slug, p.name FROM architecture.jobs j JOIN architecture.projects p ON j.project_id = p.id WHERE j.stage = '${STAGE}' ORDER BY j.created_at DESC LIMIT 10`;
    break;

  case 'artifacts':
    response.action = 'query_db';
    response.queryType = 'artifacts';
    response.sql = projectSlug
      ? `SELECT a.id, a.type, a.version, a.created_at, p.slug, p.name FROM architecture.artifacts a JOIN architecture.projects p ON a.project_id = p.id WHERE a.type = '${ARTIFACT_TYPE}' AND p.slug = '${projectSlug}' ORDER BY a.version DESC LIMIT 10`
      : `SELECT a.id, a.type, a.version, a.created_at, p.slug, p.name FROM architecture.artifacts a JOIN architecture.projects p ON a.project_id = p.id WHERE a.type = '${ARTIFACT_TYPE}' ORDER BY a.created_at DESC LIMIT 10`;
    break;

  case 'jobs':
    response.action = 'query_db';
    response.queryType = 'jobs';
    response.sql = `SELECT j.id, j.stage, j.status, j.created_at, j.completed_at, p.slug, p.name FROM architecture.jobs j JOIN architecture.projects p ON j.project_id = p.id WHERE j.stage = '${STAGE}' ORDER BY j.created_at DESC LIMIT 20`;
    break;

  case 'list':
    response.action = 'query_db';
    response.queryType = 'projects';
    response.sql = `SELECT p.id, p.slug, p.name, p.created_at, p.updated_at, (SELECT COUNT(*) FROM architecture.artifacts a WHERE a.project_id = p.id AND a.type = '${ARTIFACT_TYPE}') as brd_count, (SELECT COUNT(*) FROM architecture.jobs j WHERE j.project_id = p.id AND j.stage = '${STAGE}') as job_count FROM architecture.projects p ORDER BY p.updated_at DESC LIMIT 20`;
    break;

  default:
    response.success = false;
    response.message = `Unknown intent: ${intent}`;
    response.content = 'Try "help" to see available commands.';
}

return [{ json: response }];

parameters.query:
CREATE SCHEMA IF NOT EXISTS architecture;

CREATE TABLE IF NOT EXISTS architecture.projects (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text UNIQUE NOT NULL,
  name text,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS architecture.artifacts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES architecture.projects(id),
  type text NOT NULL,
  version int NOT NULL,
  content jsonb NOT NULL,
  content_hash text NOT NULL,
  meta jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz DEFAULT now()
);

CREATE INDEX IF NOT EXISTS artifacts_project_type_version_idx ON architecture.artifacts(project_id, type, version DESC);

CREATE TABLE IF NOT EXISTS architecture.jobs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid REFERENCES architecture.projects(id),
  stage varchar(50) NOT NULL,
  input_job_id uuid REFERENCES architecture.jobs(id),
  status varchar(20) DEFAULT 'running',
  created_at timestamptz DEFAULT now(),
  completed_at timestamptz,
  meta jsonb DEFAULT '{}'::jsonb
);

CREATE INDEX IF NOT EXISTS jobs_project_stage_idx ON architecture.jobs(project_id, stage, created_at DESC);

INSERT INTO architecture.jobs (project_id, stage, status, meta)
VALUES ($1, 'business-analysis', 'running', $2::jsonb)
RETURNING id, stage, status, created_at;

