// Validate BRD structure
const raw = $json.message?.content;
let brd;
try {
  brd = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  return [{ json: { ...$json, valid: false, errors: ['BRD JSON parse failed: ' + e.message], brd: null } }];
}

const errors = [];
if (brd?.type !== 'brd') errors.push('type must be brd');
if (!brd?.title) errors.push('title is required');
if (!brd?.executiveSummary) errors.push('executiveSummary is required');
if (!brd?.problemStatement) errors.push('problemStatement is required');
if (!Array.isArray(brd?.businessObjectives)) errors.push('businessObjectives must be array');
if (!Array.isArray(brd?.stakeholders)) errors.push('stakeholders must be array');
if (!brd?.scope) errors.push('scope is required');

const fnv1a = (input) => {
  const str = String(input ?? '');
  let hash = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = (hash * 0x01000193) >>> 0;
  }
  return ('0000000' + hash.toString(16)).slice(-8);
};

const valid = errors.length === 0;
const brdHash = fnv1a(JSON.stringify(brd));

return [{ json: { ...$json, valid, errors, brd, brdHash } }];

// Build BRD.md content from validated BRD
const ctx = $('Pass Context').first().json;
const brd = $('Validate BRD').first().json.brd;

const fmt = (item, field) => {
  if (typeof item === 'string') return item;
  if (item && typeof item === 'object') {
    if (field && item[field]) return item[field];
    if (item.description) return item.description;
    if (item.name) return item.name;
    return JSON.stringify(item);
  }
  return String(item);
};

const fmtObjective = (o) => {
  if (typeof o === 'string') return o;
  const desc = o.description || '';
  const metric = o.metric ? ` (Metric: ${o.metric})` : '';
  const date = o.targetDate ? ` [Target: ${o.targetDate}]` : '';
  return `${desc}${metric}${date}`;
};

const fmtStakeholder = (s) => {
  if (typeof s === 'string') return s;
  const name = s.name || 'Unknown';
  const desc = s.description ? `: ${s.description}` : '';
  const reqs = Array.isArray(s.requirements) && s.requirements.length > 0 ? `\n  - Requirements: ${s.requirements.join(', ')}` : '';
  return `**${name}**${desc}${reqs}`;
};

const fmtConstraint = (c) => {
  if (typeof c === 'string') return c;
  const desc = c.description || '';
  const impact = c.impact ? ` (Impact: ${c.impact})` : '';
  return `${desc}${impact}`;
};

const fmtAssumption = (a) => {
  if (typeof a === 'string') return a;
  const desc = a.description || '';
  const rationale = a.rationale ? ` (Rationale: ${a.rationale})` : '';
  return `${desc}${rationale}`;
};

const fmtCriteria = (s) => {
  if (typeof s === 'string') return s;
  const desc = s.description || '';
  const date = s.targetDate ? ` [Target: ${s.targetDate}]` : '';
  return `${desc}${date}`;
};

const md = [
  `# Business Requirements Document: ${ctx.projectName}`,
  '',
  `## Executive Summary`,
  '',
  brd?.executiveSummary || '',
  '',
  '## Problem Statement',
  '',
  `### Current State`,
  brd?.problemStatement?.currentState || '',
  '',
  '### Pain Points',
  ...(Array.isArray(brd?.problemStatement?.painPoints) ? brd.problemStatement.painPoints.map(p => `- ${p}`) : ['- N/A']),
  '',
  `### Impact`,
  brd?.problemStatement?.impact || '',
  '',
  '## Business Objectives',
  ...(Array.isArray(brd?.businessObjectives) ? brd.businessObjectives.map(o => `- ${fmtObjective(o)}`) : ['- N/A']),
  '',
  '## Success Metrics (KPIs)',
  ...(Array.isArray(brd?.successCriteria) ? brd.successCriteria.map(s => `- ${fmtCriteria(s)}`) : ['- N/A']),
  '',
  '## Stakeholders',
  ...(Array.isArray(brd?.stakeholders) ? brd.stakeholders.map(s => `- ${fmtStakeholder(s)}`) : ['- N/A']),
  '',
  '## Constraints & Assumptions',
  '### Constraints',
  ...(Array.isArray(brd?.constraints) ? brd.constraints.map(c => `- ${fmtConstraint(c)}`) : ['- N/A']),
  '',
  '### Assumptions',
  ...(Array.isArray(brd?.assumptions) ? brd.assumptions.map(a => `- ${fmtAssumption(a)}`) : ['- N/A']),
  '',
  '## Scope',
  '',
  '### In Scope',
  ...(Array.isArray(brd?.scope?.inclusions) ? brd.scope.inclusions.map(f => `- ${f}`) : (brd?.scope?.inScope ? [brd.scope.inScope] : ['- N/A'])),
  '',
  '### Out of Scope',
  ...(Array.isArray(brd?.scope?.exclusions) ? brd.scope.exclusions.map(f => `- ${f}`) : (Array.isArray(brd?.scope?.outOfScope) ? brd.scope.outOfScope.map(f => `- ${f}`) : ['- N/A'])),
].join('\n');

return [{ json: { ...ctx, brdMarkdown: md, brd } }];

// Build git script for BRD.md commit
const ctx = $json;
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;

const repoDir = '/opt/workspace/software-delivery';
const projectDir = repoDir + '/' + projectSlug + '-docs';
const remote = 'git@github.com:shlapolosa/software-delivery.git';

let sh = '';
sh += 'set -e\n';
sh += 'mkdir -p /opt/workspace\n';
sh += "if [ ! -d '" + repoDir + "/.git' ]; then git clone '" + remote + "' '" + repoDir + "'; fi\n";
sh += "cd '" + repoDir + "'\n";
sh += "git remote set-url origin '" + remote + "'\n";
sh += 'git fetch origin\n';
sh += "git checkout -B '" + projectSlug + "' 'origin/" + projectSlug + "' 2>/dev/null || git checkout -B '" + projectSlug + "'\n";
sh += "mkdir -p '" + projectDir + "/docs'\n";

sh += "cat > '" + projectDir + "/docs/BRD.md' <<'EOF_" + jobId + "'\n";
sh += ctx.brdMarkdown + "\nEOF_" + jobId + "\n";

sh += "git add '" + projectSlug + "-docs/docs/BRD.md'\n";
sh += "git commit -m 'Add BRD for " + projectSlug + " (job " + jobId + ")' || true\n";
sh += "git push -u origin '" + projectSlug + "'\n";

return [{ json: { ...ctx, gitScript: sh } }];

// Return result to caller
const ctx = $('Pass Context').first().json;
return [{ json: {
  success: true,
  jobId: ctx.jobId,
  projectSlug: ctx.projectSlug,
  stage: 'business-analysis',
  brdPath: ctx.projectSlug + '-docs/docs/BRD.md'
} }];

// Parse and normalize incoming request
// Detect Open WebUI system prompts (auto-tagging, follow-ups, title generation)
const input = $json.body || $json;

// Check multiple possible field names for user input
// Open WebUI may send as chatInput, projectSlug, message, or query
const chatInput = input.chatInput || input.message || input.query || input.projectSlug || '';
const requirements = input.requirements || '';

// Detect Open WebUI system prompts
const isAutoTag = chatInput.includes('### Task:') && chatInput.includes('Generate 1-3 broad tags');
const isFollowUp = chatInput.includes('### Task:') && chatInput.includes('Suggest 3-5 relevant follow-up');
const isTitleGen = chatInput.includes('### Task:') && chatInput.includes('Generate a concise');
const isSystemPrompt = isAutoTag || isFollowUp || isTitleGen;

// Also check requirements field for system prompts
const reqIsAutoTag = requirements.includes('### Task:') && requirements.includes('Generate 1-3 broad tags');
const reqIsFollowUp = requirements.includes('### Task:') && requirements.includes('Suggest 3-5 relevant follow-up');
const reqIsTitleGen = requirements.includes('### Task:') && requirements.includes('Generate a concise');
const reqIsSystemPrompt = reqIsAutoTag || reqIsFollowUp || reqIsTitleGen;

// Determine system prompt type
let systemPromptType = null;
if (isAutoTag || reqIsAutoTag) systemPromptType = 'auto-tag';
else if (isFollowUp || reqIsFollowUp) systemPromptType = 'follow-up';
else if (isTitleGen || reqIsTitleGen) systemPromptType = 'title-gen';

// Only use projectSlug from input if it looks like a slug (no spaces, short)
// Otherwise it might be the user message sent with wrong field name
const inputProjectSlug = input.projectSlug || null;
const looksLikeSlug = inputProjectSlug && inputProjectSlug.length < 100 && !inputProjectSlug.includes(' ');
const actualProjectSlug = looksLikeSlug ? inputProjectSlug : null;

// FIX: Use requirements as fallback for rawInput when not a system prompt
// This handles Open WebUI sending user messages in the requirements field
let rawInput = chatInput;
if (!rawInput && !(isSystemPrompt || reqIsSystemPrompt) && requirements) {
  rawInput = requirements;
}

return [{ json: {
  rawInput: rawInput,
  projectSlug: actualProjectSlug,
  projectName: input.projectName || null,
  requirements: input.requirements || null,
  sessionId: input.sessionId || null,
  isSystemPrompt: isSystemPrompt || reqIsSystemPrompt,
  systemPromptType: systemPromptType
} }];

