    externalResearch.map((r, idx) =>
      `${idx + 1}. **${r.title}**\n   ${r.snippet}\n   Source: ${r.url}`
    ).join('\n\n');
}

// Combine and truncate to avoid exceeding context limits
const fullContext = [internalContext, externalContext]
  .filter(Boolean)
  .join('\n\n---\n\n')
  .slice(0, 4000);

// Pass through the original context
const passContext = classifyData?.passContext || $('Pass Context').first()?.json || {};

