// Parse LLM response and filter nouns
const response = $input.first().json;
const requirements = $('Pass Context').first().json.requirements || '';
let nouns = [];

try {
  const content = response.message?.content || '[]';
  const parsed = JSON.parse(content);
  nouns = Array.isArray(parsed) ? parsed : (parsed.nouns || []);
} catch (e) {
  // Fallback: extract array from text
  const match = (response.message?.content || '').match(/\[([^\]]+)\]/);
  if (match) {
    nouns = match[1].split(',').map(s => s.trim().replace(/['"]/g, '').toLowerCase());
  }
}

// Filter short words and deduplicate
nouns = [...new Set(nouns.filter(n => n && n.length > 2))];

return [{
  json: {
    requirements,
    extractedNouns: nouns,
    nounCount: nouns.length,
    passContext: $('Pass Context').first().json
  }
}];

// Classify nouns as internal vs external via Qdrant
const nouns = $input.first().json.extractedNouns || [];
const passContext = $input.first().json.passContext;

if (nouns.length === 0) {
  return [{
    json: {
      internalNouns: [],
      externalNouns: [],
      researchNeeded: false,
      searchQuery: '',
      embedding: null,
      qdrantHitCount: 0,
      passContext
    }
  }];
}

// Create combined search query
const combinedQuery = nouns.join(' ');

// Get embedding for combined query using this.helpers.httpRequest
let embedding = null;
try {
  const embeddingResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://ollama:11434/api/embeddings',
    body: {
      model: 'nomic-embed-text',
      prompt: combinedQuery
    },
    json: true
  });
  embedding = embeddingResponse.embedding;
} catch (e) {
  // Embedding failed - treat all as external
  return [{
    json: {
      internalNouns: [],
      externalNouns: nouns,
      researchNeeded: nouns.length > 0,
      searchQuery: nouns.slice(0, 5).join(' '),
      embedding: null,
      qdrantHitCount: 0,
      error: 'Embedding generation failed: ' + e.message,
      passContext
    }
  }];
}

// Query Qdrant for internal knowledge
let qdrantResults = [];
try {
  const qdrantResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://qdrant:6333/collections/agent-knowledge-business-analyst/points/search',
    body: {
      vector: embedding,
      limit: 10,
      with_payload: true,
      score_threshold: 0.65
    },
    json: true
  });
  qdrantResults = qdrantResponse.result || [];
} catch (e) {
  // Qdrant query failed (maybe collection doesn't exist) - treat all as external
  qdrantResults = [];
}

// Extract internal concepts from Qdrant hits
const internalConcepts = new Set();
qdrantResults.forEach(hit => {
  const scope = hit.payload?.metadata?.scope || {};
  (scope.internalSystems || []).forEach(s => internalConcepts.add(s.toLowerCase()));
  (scope.internalCapabilities || []).forEach(c => internalConcepts.add(c.toLowerCase()));
  (scope.supportedIntegrations || []).forEach(i => internalConcepts.add(i.toLowerCase()));

  // Check content for direct mentions
  const content = (hit.payload?.content || '').toLowerCase();
  nouns.forEach(noun => {
    if (content.includes(noun.toLowerCase())) {
      internalConcepts.add(noun.toLowerCase());
    }
  });
});

// Classify nouns
const internalNouns = nouns.filter(n => internalConcepts.has(n.toLowerCase()));
const externalNouns = nouns.filter(n => !internalConcepts.has(n.toLowerCase()));

return [{
  json: {
    internalNouns,
    externalNouns,
    researchNeeded: externalNouns.length > 0,
    searchQuery: externalNouns.slice(0, 5).join(' '),
    embedding,
    qdrantHitCount: qdrantResults.length,
    classificationDetails: {
      totalNouns: nouns.length,
      internalCount: internalNouns.length,
      externalCount: externalNouns.length
    },
    passContext
  }
}];

