// Parse and format research results - handle missing upstream nodes gracefully
let classifyData = {};
let internalRulesRaw = [];
let externalSearchRaw = [];

// Safely get data from Classify Nouns (Qdrant)
try {
  classifyData = $('Classify Nouns (Qdrant)').first()?.json || {};
} catch (e) {
  classifyData = {};
}

// Safely get data from Query Internal Rules
try {
  internalRulesRaw = $('Query Internal Rules').first()?.json?.result || [];
} catch (e) {
  internalRulesRaw = [];
}

// Safely get data from SearXNG Research
try {
  externalSearchRaw = $('SearXNG Research').first()?.json?.results || [];
} catch (e) {
  externalSearchRaw = [];
}

// Format internal rules (high confidence only)
const internalRules = (Array.isArray(internalRulesRaw) ? internalRulesRaw : [])
  .filter(r => r.score >= 0.7)
  .map(r => ({
    content: r.payload?.content || '',
    scope: r.payload?.metadata?.scope || {},
    score: r.score
  }));

// Format external research (top 3 results)
const externalResearch = (Array.isArray(externalSearchRaw) ? externalSearchRaw : [])
  .slice(0, 3)
  .map(r => ({
    title: r.title || '',
    snippet: (r.content || r.snippet || '').slice(0, 500),
    url: r.url || ''
  }))
  .filter(r => r.title);

return [{
  json: {
    internalRules,
    externalResearch,
    internalCount: internalRules.length,
    externalCount: externalResearch.length,
    classifyData
  }
}];

// Aggregate research context for BRD generation
// Handle both branches: from Parse Results (research done) or direct from If (no research needed)
let classifyData, parsedData;

try {
  // Try to get from research path
  parsedData = $('Parse Research Results').first()?.json;
  classifyData = parsedData?.classifyData || $('Classify Nouns (Qdrant)').first().json;
} catch (e) {
  // Direct path - no research was done
  classifyData = $('Classify Nouns (Qdrant)').first().json;
  parsedData = { internalRules: [], externalResearch: [] };
}

const internalRules = parsedData?.internalRules || [];
const externalResearch = parsedData?.externalResearch || [];

// Build internal context section
let internalContext = '';
if (internalRules.length > 0) {
  internalContext = '## Internal Business Rules & System Constraints\n\n' +
    'The following internal systems and rules apply:\n\n' +
    internalRules.map((r, idx) =>
      `${idx + 1}. ${(r.content || '').slice(0, 600)}\n   (Relevance: ${Math.round((r.score || 0) * 100)}%)`
    ).join('\n\n');
}

// Build external context section
let externalContext = '';
if (externalResearch.length > 0) {
  externalContext = '## External System Integration Research\n\n' +
    'Research findings for external dependencies:\n\n' +
    externalResearch.map((r, idx) =>
      `${idx + 1}. **${r.title}**\n   ${r.snippet}\n   Source: ${r.url}`
    ).join('\n\n');
}

// Combine and truncate to avoid exceeding context limits
const fullContext = [internalContext, externalContext]
  .filter(Boolean)
  .join('\n\n---\n\n')
  .slice(0, 4000);

// Pass through the original context
const passContext = classifyData?.passContext || $('Pass Context').first()?.json || {};

return [{
  json: {
    ...passContext,
    researchContext: fullContext,
    internalNouns: classifyData?.internalNouns || [],
    externalNouns: classifyData?.externalNouns || [],
    hasInternalRules: internalRules.length > 0,
    hasExternalResearch: externalResearch.length > 0,
    researchSummary: {
      totalNouns: (classifyData?.internalNouns?.length || 0) + (classifyData?.externalNouns?.length || 0),
      internalRulesFound: internalRules.length,
      externalSourcesFound: externalResearch.length
    }
  }
}];

// Build Azure DevOps push payload
const ctx = $("Build Git Script").first().json;
const repoInfo = $("Get Azure Repo Info").first().json;
const branchCheck = $json;
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;

// Get artifact content
const artifactContent = ctx.brdMarkdown || ctx.artifactMarkdown || ctx.content || "";
const artifactPath = "/docs/BRD.md";

// Determine branch reference
const branchName = `refs/heads/${projectSlug}`;

// Check if branch exists and get its current commit SHA
let oldObjectId = "0000000000000000000000000000000000000000";
let changeType = "add";

if (branchCheck.value && branchCheck.value.length > 0) {
  // Branch exists - use current commit SHA for update
  oldObjectId = branchCheck.value[0].objectId;
  changeType = "edit"; // Update existing file
}

// Build the push payload
const changes = [{
  changeType: changeType,
  item: { path: `/${projectSlug}-docs${artifactPath}` },
  newContent: {
    content: Buffer.from(artifactContent).toString("base64"),
    contentType: "base64encoded"
  }
}];

return [{
  json: {
    ...ctx,
    azurePushPayload: {
      refUpdates: [{
        name: branchName,
        oldObjectId: oldObjectId
      }],
      commits: [{
        comment: `Add artifacts for ${projectSlug} (job ${jobId})`,
        changes: changes
      }]
    },
    azureRepoInfo: repoInfo,
    branchExists: branchCheck.value && branchCheck.value.length > 0
  }
}];
